"use client";

import { usePathname } from "next/navigation";
import { Header } from "@/components/layout/Header";
import { Footer } from "@/components/layout/Footer";
import { SupportChatWidget } from "@/components/layout/SupportChatWidget";

// The admin console (spec §24-27) is a distinct surface with its own AdminSidebar/AdminGate —
// the public marketing header/footer would just be visual noise on top of it. This is the one
// path-based exception; every other route keeps the standard site chrome.
export function SiteChrome({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();
  const isAdmin = pathname?.startsWith("/admin");

  if (isAdmin) return <>{children}</>;

  return (
    <>
      <Header />
      <main className="flex-1">{children}</main>
      <Footer />
      <SupportChatWidget />
    </>
  );
}
