"use client";

import { useState, useRef, useEffect } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { ChevronDown, Heart, Bookmark, CalendarClock, MessageSquare, LayoutDashboard, LogOut } from "lucide-react";
import { useAuth } from "@/lib/auth";
import { authService } from "@/lib/services/auth.service";
import { useChatRooms } from "@/lib/chat";
import { toast } from "@/lib/toast";

export function UserMenu() {
  const { user } = useAuth();
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  const rooms = useChatRooms();
  const unreadMessages = rooms.reduce((sum, r) => sum + r.unreadCount, 0);

  useEffect(() => {
    if (!open) return;
    const onClick = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, [open]);

  if (!user) return null;

  const initials = user.name.split(" ").map((n) => n[0]).join("").slice(0, 2);
  const links = [
    { href: "/messages", label: "Messages", icon: MessageSquare, badge: unreadMessages },
    { href: "/favorites", label: "Favorites", icon: Heart },
    { href: "/saved-searches", label: "Saved Searches", icon: Bookmark },
    { href: "/visits", label: "Scheduled Visits", icon: CalendarClock },
    ...(user.role !== "tenant" && user.role !== "buyer"
      ? [{ href: "/owner/dashboard", label: "Owner Dashboard", icon: LayoutDashboard }]
      : []),
  ];

  async function logout() {
    await authService.logout();
    setOpen(false);
    toast("Logged out");
    router.push("/");
  }

  return (
    <div className="relative" ref={ref}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        aria-expanded={open}
        className="flex items-center gap-2 rounded-full py-1 pl-1 pr-2.5 hover:bg-muted"
      >
        <span className="flex h-8 w-8 items-center justify-center rounded-full bg-brand-navy-light text-xs font-bold text-brand-navy">
          {initials}
        </span>
        <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <div className="absolute right-0 top-full mt-2 w-56 overflow-hidden rounded-xl border border-border bg-white py-1.5 shadow-xl">
          <div className="border-b border-border px-3.5 py-2.5">
            <p className="text-sm font-semibold text-foreground">{user.name}</p>
            <p className="text-xs capitalize text-muted-foreground">{user.role}</p>
          </div>
          {links.map((l) => (
            <Link
              key={l.href}
              href={l.href}
              onClick={() => setOpen(false)}
              className="flex items-center gap-2.5 px-3.5 py-2 text-sm text-foreground hover:bg-muted"
            >
              <l.icon className="h-4 w-4 text-muted-foreground" /> {l.label}
              {"badge" in l && !!l.badge && (
                <span className="ml-auto flex h-4 min-w-4 items-center justify-center rounded-full bg-brand-orange px-1 text-[10px] font-bold text-white">
                  {l.badge}
                </span>
              )}
            </Link>
          ))}
          <button
            type="button"
            onClick={logout}
            className="flex w-full items-center gap-2.5 border-t border-border px-3.5 py-2 text-sm font-medium text-red-600 hover:bg-red-50"
          >
            <LogOut className="h-4 w-4" /> Logout
          </button>
        </div>
      )}
    </div>
  );
}
